#include <stdio.h>
#include <math.h>
int main(void) {
    const double target = 2.5;
    const double tolerance = 0.01;
    double candidate = 0.0;
    if (scanf("%lf", &candidate) != 1) return 1;
    while (fabs(candidate - target) > tolerance) {
        printf("retry\n");
        if (scanf("%lf", &candidate) != 1) return 1;
    }
    printf("accepted\n");
    return 0;
}

