#include <stdio.h>
int main(void) {
    int records[3];
    for (int i = 0; i < 3; i++) {
        if (scanf("%d", &records[i]) != 1) return 1;
    }
    int sum = 0;
    for (int i = 0; i < 3; i++) {
        sum += records[i];
    }
    double average = (double)sum / 3;
    printf("sum=%d mean=%.2f difference=%.2f\n", sum, average, average - 8.0);
    return 0;
}

#include <stdio.h>
double repeated_power(double base, int exponent);
int main(void) {
    double base = 0.0;
    int exponent = 0;
    while (scanf("%lf", &base) == 1) {
        if (scanf("%d", &exponent) != 1) return 1;
        if (exponent < 0 || exponent > 8) return 1;
        double answer = repeated_power(base, exponent);
        printf("%.2f\n", answer);
    }
    return 0;
}
double repeated_power(double base, int exponent) {
    double product = 1.0;
    for (int done = 0; done < exponent; done++) {
        product *= base;
    }
    return product;
}

