#include <stdio.h>
int main(void) {
    int limit = 0;
    if (scanf("%d", &limit) != 1) return 1;
    int sum = 0;
    int current = 1;
    if (limit > 0) {
        do {
            sum += current;
            current++;
        } while (current <= limit);
    }
    printf("%d\n", sum * 6);
    return 0;
}
